// Exact factors to one. Per BIPM SI Brochure, including 2022 additions.
var TABLE=[["quecto","q",1e-30], ["ronto","r",1e-27], ["yocto","y",1e-24], ["zepto","z",1e-21], ["atto","a",1e-18], ["femto","f",1e-15], ["pico","p",1e-12], ["nano","n",1e-09], ["micro","u",1e-06], ["milli","m",0.001], ["centi","c",0.01], ["deci","d",0.1], ["one","1",1.0], ["deca","da",10.0], ["hecto","h",100.0], ["kilo","k",1000.0], ["mega","M",1000000.0], ["giga","G",1000000000.0], ["tera","T",1000000000000.0], ["peta","P",1000000000000000.0], ["exa","E",1e+18], ["zetta","Z",1e+21], ["yotta","Y",1e+24], ["ronna","R",1e+27], ["quetta","Q",1e+30]];
function toBase(v,name){name=String(name).toLowerCase();for(var i=0;i<TABLE.length;i++){if(TABLE[i][0].toLowerCase()===name||TABLE[i][1].toLowerCase()===name)return v*TABLE[i][2];}throw new Error("unknown unit: "+name);}
function convert(v,from,to){var b=toBase(v,from);to=String(to).toLowerCase();for(var i=0;i<TABLE.length;i++){if(TABLE[i][0].toLowerCase()===to||TABLE[i][1].toLowerCase()===to)return b/TABLE[i][2];}throw new Error("unknown unit: "+to);}
